#!/usr/bin/env bash
# Golden e2e — one unattended `/mango:autorun` on a generated sample project, judged on artifacts.
#
#   bash tests/e2e/run.sh [--local] [--keep]
#
# It costs tokens: one full lifecycle with its subagents. CI runs it weekly and on demand
# (.github/workflows/e2e.yml), never on push. Outside CI it refuses to start without --local, because
# the dispatched session may edit files and run git/python inside the sandbox without asking.
#
# Isolation: the plugin under test is a clone of this repo's HEAD (commit before running), the
# project is generated by make_sample.sh under a temp dir, the remote is a local bare repo, and
# `gh` on PATH is a test double that never contacts a server. The live checkout is never touched.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(git -C "$HERE" rev-parse --show-toplevel)"
LOCAL=0; KEEP=0
for arg in "$@"; do
  case "$arg" in
    --local) LOCAL=1 ;;
    --keep) KEEP=1 ;;
    *) echo "usage: run.sh [--local] [--keep]" >&2; exit 1 ;;
  esac
done
if [ "${CI:-}" != "true" ] && [ "$LOCAL" -ne 1 ]; then
  echo "e2e: refusing to start outside CI without --local (it dispatches an unattended session that edits files)." >&2
  exit 1
fi
command -v claude >/dev/null || { echo "e2e: 'claude' CLI not found on PATH" >&2; exit 1; }
if [ -z "${ANTHROPIC_API_KEY:-}" ] && ! claude auth status --json 2>/dev/null | grep -qE '"loggedIn"[[:space:]]*:[[:space:]]*true'; then
  echo "e2e: claude is not authenticated — export ANTHROPIC_API_KEY or log in." >&2
  exit 1
fi
if [ -n "$(git -C "$REPO_ROOT" status --porcelain -- plugins tests/e2e)" ]; then
  echo "e2e: uncommitted changes under plugins/ or tests/e2e/ — the run clones HEAD, so commit first." >&2
  exit 1
fi

TMP="$(mktemp -d)"
cleanup() { [ "$KEEP" -eq 1 ] && echo "e2e: kept $TMP" || rm -rf "$TMP"; }
trap cleanup EXIT

git clone -q "$REPO_ROOT" "$TMP/mango"
PLUGIN="$TMP/mango/plugins/mango"
SAMPLE="$(bash "$TMP/mango/tests/e2e/make_sample.sh" "$TMP/sample")"
BASE="$(git -C "$SAMPLE/work" rev-parse HEAD)"
LIVE_HEAD="$(git -C "$REPO_ROOT" rev-parse HEAD)"
RUN_ID="$(date -u +%Y%m%dT%H%M%SZ)"
OUT="$HERE/.runs/$RUN_ID"; mkdir -p "$OUT"

PROMPT="/mango:autorun PROJ-901

Handover authorisation: I authorise exactly two outward actions for this run — push the feature branch
for PROJ-901 to origin, and open its pull request through pr_host. Nothing else."

ALLOWED='Read Edit Write Glob Grep Agent Task TodoWrite Skill
Bash(git:*) Bash(python3:*) Bash(python:*) Bash(gh:*) Bash(rtk:*) Bash(ls:*) Bash(cat:*) Bash(head:*)
Bash(tail:*) Bash(wc:*) Bash(grep:*) Bash(sed:*) Bash(awk:*) Bash(find:*) Bash(mkdir:*) Bash(test:*)
Bash(echo:*) Bash(printf:*) Bash(diff:*) Bash(cp:*) Bash(mv:*) Bash(touch:*) Bash(sort:*) Bash(cd:*)
Bash(pwd:*) Bash(date:*) Bash(which:*) Bash(command:*) Bash(true:*) Bash(PYTHONPATH=*)
Bash(printenv:*) Bash(tr:*) Bash(cut:*) Bash(uniq:*) Bash(basename:*) Bash(dirname:*) Bash(realpath:*) Bash(nl:*)'

echo "== golden e2e: dispatch (mango $(python3 -c "import json;print(json.load(open('$PLUGIN/.claude-plugin/plugin.json'))['version'])") @ $(git -C "$TMP/mango" rev-parse --short HEAD)) =="
START=$(date +%s)
set +e
( cd "$SAMPLE/work" \
  && env -u GH_TOKEN -u GITHUB_TOKEN PATH="$SAMPLE/bin:$PATH" MANGO_E2E_DIR="$SAMPLE" \
     timeout "${MANGO_E2E_TIMEOUT:-5400}" claude -p --plugin-dir "$PLUGIN" --output-format json \
       --permission-mode acceptEdits --allowedTools $ALLOWED --max-turns "${MANGO_E2E_MAX_TURNS:-400}" \
       "$PROMPT" </dev/null >"$OUT/result.json" 2>"$OUT/stderr.txt" )
DISPATCH_EXIT=$?
set -e
WALL=$(( $(date +%s) - START ))

cp "$SAMPLE/pr-log.jsonl" "$OUT/" 2>/dev/null || true
cp "$SAMPLE/work/docs/tickets/PROJ-901.work.md" "$OUT/" 2>/dev/null || true
cp -r "$SAMPLE/work/.mango" "$OUT/mango-run" 2>/dev/null || true

COST="$(python3 - "$OUT/result.json" <<'EOF'
import json, sys
try:
    r = json.load(open(sys.argv[1]))
except Exception:
    print("cost unknown (no JSON result)"); sys.exit()
u = r.get("usage") or {}
print(f"cost_usd={r.get('total_cost_usd', 'unknown')} turns={r.get('num_turns', 'unknown')} "
      f"input={u.get('input_tokens', '?')} output={u.get('output_tokens', '?')} "
      f"cache_read={u.get('cache_read_input_tokens', '?')} subtype={r.get('subtype', '?')}")
EOF
)"
echo "dispatch exit $DISPATCH_EXIT · wall ${WALL}s · $COST"

set +e
python3 "$HERE/assert_run.py" --dir "$SAMPLE" --base "$BASE" --mango "$PLUGIN" | tee "$OUT/assertions.txt"
VERDICT=${PIPESTATUS[0]}
set -e

[ "$(git -C "$REPO_ROOT" rev-parse HEAD)" = "$LIVE_HEAD" ] || { echo "e2e: FAIL — the live checkout's HEAD moved" >&2; VERDICT=1; }
echo "e2e: artifacts kept in $OUT"

if [ -n "${GITHUB_STEP_SUMMARY:-}" ]; then
  {
    echo "### Golden e2e — $( [ "$VERDICT" -eq 0 ] && echo green || echo RED )"
    echo
    echo "- dispatch exit: \`$DISPATCH_EXIT\` · wall-clock: ${WALL}s"
    echo "- $COST"
    echo
    echo '```'
    cat "$OUT/assertions.txt"
    echo '```'
  } >>"$GITHUB_STEP_SUMMARY"
fi
exit "$VERDICT"
